<template>
  <iframe :height="height" :src="youtubeUrl" :title="title" :width="width"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          allowfullscreen frameborder="0" referrerpolicy="strict-origin-when-cross-origin"/>
</template>

<script lang="ts">
  import { Component, Prop, Vue } from 'vue-property-decorator'

  @Component
  export default class CSYoutubeVideo extends Vue {

    @Prop({ required: true }) videoId!: string
    @Prop({ required: true }) width!: string
    @Prop({ required: true }) height!: string

    get title(): string {
      return `YouTube video ${this.videoId}`
    }

    get youtubeUrl(): string {
      const params = new URLSearchParams({
        modestbranding: '1',
        playsinline: '1',
        rel: '0'
      })
      return `https://www.youtube-nocookie.com/embed/${encodeURIComponent(this.videoId)}?${params.toString()}`
    }
  }
</script>
