<template>
  <div>
    <v-container fluid grid-list-md>
      <template v-for="group in imageGroups">
        <div :class="`gallery-grid--${group.orientation}`"
             :key="group.orientation"
             class="gallery-grid"
             v-if="group.images.length">
          <v-card :aria-label="entry.alt"
                  :key="entry.index"
                  :style="{'--gallery-image-ratio': entry.aspectRatio}"
                  @click="showFullScreenImage(entry.index)"
                  @keydown.enter.prevent="showFullScreenImage(entry.index)"
                  @keydown.space.prevent="showFullScreenImage(entry.index)"
                  class="site-card site-card--interactive gallery-card"
                  flat
                  ripple
                  role="button"
                  tabindex="0"
                  v-for="entry in group.images"
                  width="100%">
            <CSImage :alt="entry.alt" :src="entry.image" height="100%" width="100%"/>
          </v-card>
        </div>
      </template>
    </v-container>
    <CSImageViewer :imageAlts="viewerImageAlts" :images="viewerImages" ref="imageViewer"/>
  </div>
</template>

<style lang="stylus" scoped>
.gallery-grid
  display grid
  gap 12px

.gallery-grid + .gallery-grid
  margin-top 12px

.gallery-grid--landscape
  grid-template-columns repeat(2, minmax(0, 1fr))

.gallery-grid--portrait
  grid-template-columns repeat(4, minmax(0, 1fr))

.gallery-card
  position relative
  aspect-ratio var(--gallery-image-ratio)
  cursor pointer

.gallery-card .cs-image
  position absolute
  inset 0

@media (max-width: $site-bp-tablet)
  .gallery-grid--portrait
    grid-template-columns repeat(3, minmax(0, 1fr))

@media (max-width: $site-bp-mobile)
  .gallery-grid--landscape
    grid-template-columns 1fr

  .gallery-grid--portrait
    grid-template-columns repeat(2, minmax(0, 1fr))
</style>

<script lang="ts">
  import { Component, Prop, Watch } from 'vue-property-decorator'
  import { CSVue } from '@/cs/CSVue'
  import CSImage from '@/cs/view/CSImage.vue'
  import CSImageViewer from '@/cs/view/CSImageViewer.vue'
  import { CSImageGalleryType, CSImageViewerType } from '@/cs/vuetify/CSVuetifyTypes'

  interface GalleryImageEntry {
    image: string
    alt: string
    index: number
    width: number
    height: number
    aspectRatio: string
  }

  @Component({ components: { CSImage, CSImageViewer } })
  export default class CSImageGallery extends CSVue implements CSImageGalleryType {

    @Prop({ required: true }) images!: string[]
    @Prop({ default: () => [] }) imageAlts!: string[]
    imageEntries: GalleryImageEntry[] = []
    imageClassificationId = 0

    get imageViewer() { return this.reference<CSImageViewerType>('imageViewer') }

    get landscapeImages() { return this.imageEntries.filter(entry => entry.width >= entry.height) }
    get portraitImages() { return this.imageEntries.filter(entry => entry.width < entry.height) }
    get imageGroups() {
      return [
        { orientation: 'landscape', images: this.landscapeImages },
        { orientation: 'portrait', images: this.portraitImages }
      ]
    }
    get viewerImageEntries() { return [...this.landscapeImages, ...this.portraitImages] }
    get viewerImages() { return this.viewerImageEntries.map(entry => entry.image) }
    get viewerImageAlts() { return this.viewerImageEntries.map(entry => entry.alt) }

    imageAlt(index: number) { return this.imageAlts[index] || '' }

    mounted() {
      super.mounted()
      this.classifyImages()
    }

    @Watch('images')
    onImagesChanged() { this.classifyImages() }

    classifyImages() {
      const classificationId = ++this.imageClassificationId
      Promise.all(this.images.map((image, index) => this.classifyImage(image, index)))
        .then(entries => {
          if (classificationId === this.imageClassificationId) this.imageEntries = entries
        })
    }

    classifyImage(image: string, index: number): Promise<GalleryImageEntry> {
      return new Promise(resolve => {
        const loader = new Image()
        const finish = (width: number, height: number) => resolve({
          image,
          alt: this.imageAlt(index),
          index,
          width,
          height,
          aspectRatio: `${width} / ${height}`
        })
        loader.onload = () => finish(loader.naturalWidth || 16, loader.naturalHeight || 10)
        loader.onerror = () => finish(16, 10)
        loader.src = image
      })
    }

    showFullScreenImage(index: number) {
      const entry = this.imageEntries.find(image => image.index === index)
      if (!entry) return
      this.imageViewer.showFullScreenImage(this.viewerImageEntries.indexOf(entry))
    }

    beforeDestroy() {
      this.imageClassificationId++
    }
  }
</script>
